  ('ff4f3d67-ff47-4b5a-abc9-65255b682194'::uuid, '15 G; 7-8'' HT'::text, '7-8'''::text, NULL::text, NULL::text, '15 G'::text, '7-8'''::text, NULL::text, NULL::text),
  ('ff824cf8-01b1-49b9-8850-9de8dd67309e'::uuid, '3.5" cal'::text, NULL::text, NULL::text, NULL::text, NULL::text, NULL::text, NULL::text, '3.5"'::text),
  ('ffb18596-fddb-4318-942b-b330801e50e0'::uuid, '2.5" cal'::text, NULL::text, NULL::text, '2.5'::text, NULL::text, NULL::text, NULL::text, '2.5'::text),
  ('ffb8f147-ccc5-4fb2-a9f4-436821c6f70c'::uuid, '25 G; 1.75" Cal'::text, NULL::text, NULL::text, '1.75"'::text, '25 G'::text, NULL::text, NULL::text, '1.75"'::text)
), gate AS (
 SELECT count(*) matched FROM inventory i JOIN plan p ON p.id=i.id
 WHERE i.size IS NOT DISTINCT FROM p.old_size
   AND i.height IS NOT DISTINCT FROM p.old_height
   AND i.width IS NOT DISTINCT FROM p.old_width
   AND i.caliper IS NOT DISTINCT FROM p.old_caliper
), upd AS (
 UPDATE inventory i
 SET size=p.new_size,height=p.new_height,width=p.new_width,caliper=p.new_caliper
 FROM plan p,gate g
 WHERE g.matched=2309 AND i.id=p.id
   AND i.size IS NOT DISTINCT FROM p.old_size
   AND i.height IS NOT DISTINCT FROM p.old_height
   AND i.width IS NOT DISTINCT FROM p.old_width
   AND i.caliper IS NOT DISTINCT FROM p.old_caliper
 RETURNING i.is_active
), result AS (
 SELECT count(*) n,count(*) FILTER (WHERE is_active) active_n,count(*) FILTER (WHERE NOT is_active) inactive_n FROM upd
)
SELECT CASE WHEN n=2309 AND active_n=491 AND inactive_n=1818 THEN n ELSE 1 / (random()*0)::int END AS updated_rows FROM result;

SELECT CASE WHEN (
  SELECT count(*)=232837
     AND count(*) FILTER (WHERE is_active)=69540
     AND count(*) FILTER (WHERE NOT is_active)=163297
     AND md5(string_agg(md5((to_jsonb(i) - ARRAY['size','height','width','caliper'])::text), '' ORDER BY id))='8920860c8376c6c477ee70c631cd911e'
  FROM inventory i
) THEN 1 ELSE 1 / (random()*0)::int END AS inventory_outside_target_qa;
SELECT CASE WHEN (SELECT count(*)=1383 AND md5(string_agg(md5(to_jsonb(s)::text),'' ORDER BY id))='b5641c64eb300c7e49c423fe4a1c9f6f' FROM suppliers s)
 THEN 1 ELSE 1 / (random()*0)::int END AS suppliers_qa;
SELECT CASE WHEN (SELECT count(*)=2065 AND count(*) FILTER (WHERE is_active)=759 AND md5(string_agg(md5(to_jsonb(src)::text),'' ORDER BY id))='902aaa445da1c88b17b7f09217826740' FROM inventory_sources src)
 THEN 1 ELSE 1 / (random()*0)::int END AS sources_qa;
WITH c AS (SELECT supplier_id,count(*) n,count(*) FILTER (WHERE is_active) active_n FROM inventory GROUP BY supplier_id)
SELECT CASE WHEN md5(string_agg(md5(jsonb_build_array(supplier_id,n,active_n)::text),'' ORDER BY supplier_id))='da4168e8ba83a0ae42f50d7d3d05c0dc'
 THEN 1 ELSE 1 / (random()*0)::int END AS supplier_inventory_counts_qa FROM c;

COMMIT;
